import{a as e,c as t,i as n,t as r}from"./app-C4mzCnKe.js";var i=JSON.parse(`{"path":"/caliber-contract.html","title":"数据口径契约 v1（实库校准）","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"caliber-contract.md"}`),a={name:`caliber-contract.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="数据口径契约-v1-实库校准" tabindex="-1"><a class="header-anchor" href="#数据口径契约-v1-实库校准"><span>数据口径契约 v1（实库校准）</span></a></h1><blockquote><p>依据实库 <code>/Volumes/My PSSD/本地数据库_v2版（淘宝购买）/duckdb/taobao_minute.duckdb</code>（78 表，daily 覆盖 2000-06-09 ~ 2026-10-22，关键表更新到 2026-10-22）逐字段核实。这是「可验证性地基」的<strong>第一刀</strong>——数据管家「口径注册表」的 v1 依据。<strong>未经本契约归一的数据，不用于决策。</strong></p></blockquote><h2 id="一、五个口径地雷-已逐字段核实" tabindex="-1"><a class="header-anchor" href="#一、五个口径地雷-已逐字段核实"><span>一、五个口径地雷（已逐字段核实）</span></a></h2><h3 id="_1-1-market-语义-同一字段名-三种含义" tabindex="-1"><a class="header-anchor" href="#_1-1-market-语义-同一字段名-三种含义"><span>1.1 market 语义：同一字段名，三种含义</span></a></h3><table><thead><tr><th>表</th><th>实际取值</th><th>真实含义</th><th>样本</th></tr></thead><tbody><tr><td><code>daily.market</code></td><td><code>{hs, bj}</code></td><td><code>hs</code>=沪深合并（含 sh+sz，靠 code 前缀区分），<code>bj</code>=北交所</td><td>hs→sh600000~sz302132；bj→bj920000~bj920992</td></tr><tr><td><code>limit_price.market</code></td><td><code>{hs, bj, sz, sh}</code></td><td>混乱：<code>hs</code> 合并（16.69M 行）+ <code>bj</code>（277K）+ <code>sz</code>（8.7K）+ <code>sh</code>（6.9K），疑似重复</td><td>—</td></tr><tr><td><code>stock_info.market</code></td><td><code>{主板, 创业板, …}</code></td><td><strong>板块</strong>，不是交易所！</td><td>主板 / 创业板 / 科创板</td></tr></tbody></table><h3 id="_1-2-code-格式-两套体系并存-实跑修正-不是三种-是两套" tabindex="-1"><a class="header-anchor" href="#_1-2-code-格式-两套体系并存-实跑修正-不是三种-是两套"><span>1.2 code 格式：两套体系并存（实跑修正：不是三种，是两套）</span></a></h3><table><thead><tr><th>套系</th><th>格式</th><th>样本</th><th>覆盖表</th></tr></thead><tbody><tr><td>A 套</td><td>小写 2 字母 + 6 位</td><td><code>sz002640</code></td><td><code>daily</code> / <code>limit_price</code> / <code>adj_factor</code> / <code>daily_mv</code> / <code>index_daily</code></td></tr><tr><td>B 套</td><td>6 位 + <code>.SZ/.SH</code> 大写</td><td><code>000001.SZ</code> / <code>601100.SH</code></td><td><code>stock_info.ts_code</code> / <code>tech_factor_qfq.code</code> / <code>tech_factor_hfq.code</code> / <code>zt_pool.代码</code></td></tr></tbody></table><blockquote><p>🔴 <strong>第 6 个地雷（QC 断言 6 实跑发现）</strong>：<code>tech_factor_qfq</code> 用 B 套格式（<code>000001.SZ</code>），与 <code>daily</code> 的 A 套（<code>sz000001</code>）不同——<strong>因子表直接 join 行情表会失败</strong>。归一规则必须覆盖两张 tech_factor 表。</p></blockquote><h3 id="_1-3-date-格式-三种并存" tabindex="-1"><a class="header-anchor" href="#_1-3-date-格式-三种并存"><span>1.3 date 格式：三种并存</span></a></h3><table><thead><tr><th>表</th><th>类型</th><th>样本</th></tr></thead><tbody><tr><td><code>daily.date</code> / <code>limit_price.date</code> / <code>index_daily.date</code></td><td>DATE</td><td>2026-10-22</td></tr><tr><td><code>market_flow_daily.交易日期</code></td><td>BIGINT</td><td>20261022</td></tr><tr><td><code>suspension.交易日期</code></td><td>VARCHAR</td><td>待核实具体格式</td></tr></tbody></table><h3 id="_1-4-金额-成交量单位-至少四种" tabindex="-1"><a class="header-anchor" href="#_1-4-金额-成交量单位-至少四种"><span>1.4 金额/成交量单位：至少四种</span></a></h3><table><thead><tr><th>字段</th><th>单位</th><th>验证依据</th></tr></thead><tbody><tr><td><code>daily.amount</code></td><td><strong>元</strong></td><td>茅台 600519 日成交 5,576,216,964（约 55.76 亿）</td></tr><tr><td><code>daily.volume</code></td><td><strong>手</strong>（100 股）</td><td>55.76 亿 ÷ 1318 元 ≈ 423 万股 = 42300 手 ✓</td></tr><tr><td><code>tech_factor_qfq.amount_k</code></td><td><strong>千元</strong></td><td>字段名后缀 <code>_k</code></td></tr><tr><td><code>tech_factor_qfq.vol_hand</code></td><td><strong>手</strong></td><td>字段名后缀 <code>_hand</code></td></tr><tr><td><code>daily_mv.total_mv_yi</code> / <code>circ_mv_yi</code></td><td><strong>亿元</strong></td><td>字段名后缀 <code>_yi</code></td></tr><tr><td><code>zt_pool.主力净额(元)</code> / <code>成交额</code></td><td><strong>元</strong></td><td>字段名带 <code>(元)</code></td></tr></tbody></table><h3 id="_1-5-换手率-不在-daily-basic-在-tech-factor-qfq" tabindex="-1"><a class="header-anchor" href="#_1-5-换手率-不在-daily-basic-在-tech-factor-qfq"><span>1.5 换手率：不在 daily_basic，在 tech_factor_qfq</span></a></h3><ul><li><code>daily_basic</code> 只有 <code>total_mv / pe_ttm / pb</code>，<strong>无换手率</strong>。</li><li><code>tech_factor_qfq.turnover</code> 直接有换手率（%），且带全 <code>ma5/10/20/60、ema、macd、rsi6/12/24、kdj、boll、atr、obv、up_days/new_high_days</code> 等预计算技术因子（前复权口径）。</li><li>结论：<strong>换手率与技术因子统一从 <code>tech_factor_qfq</code> 取</strong>，不再从 daily_basic 找。</li></ul><h2 id="二、归一规则-canonical-form" tabindex="-1"><a class="header-anchor" href="#二、归一规则-canonical-form"><span>二、归一规则（canonical form）</span></a></h2><p>统一后的规范口径，所有下游表只认这一套：</p><table><thead><tr><th>维度</th><th>规范值</th><th>归一规则</th></tr></thead><tbody><tr><td>market</td><td><code>{sh, sz, bj}</code></td><td>从 code 前缀推导：<code>sh6xxxxx</code>→sh、<code>sz0/3xxxxx</code>→sz、<code>bj8/9xxxxx</code>→bj；<code>stock_info.market</code> 改字段名为 <code>board</code>，不与交易所混用</td></tr><tr><td>code</td><td><code>sz002640</code>（小写2字母+6位）</td><td><code>000001.SZ</code>↔<code>sz000001</code>；<code>601100.SH</code>↔<code>sh601100</code></td></tr><tr><td>date</td><td>DATE</td><td>BIGINT→<code>strptime(cast(x AS varchar),&#39;%Y%m%d&#39;)</code>；VARCHAR 待核实后转</td></tr><tr><td>amount</td><td>元</td><td><code>amount_k×1000</code>→元；<code>*_yi×1e8</code>→元</td></tr><tr><td>volume</td><td>股</td><td><code>手×100</code>→股</td></tr><tr><td>turnover</td><td>%</td><td>统一取 <code>tech_factor_qfq.turnover</code></td></tr></tbody></table><h2 id="三、qc-断言-机器可校验-进不了下游" tabindex="-1"><a class="header-anchor" href="#三、qc-断言-机器可校验-进不了下游"><span>三、QC 断言（机器可校验，进不了下游）</span></a></h2><p>每条口径配一条可机械执行的断言，采集层/QC 门禁直接拦：</p><ol><li><code>market ∈ {sh, sz, bj}</code> —— 非法值直接拒绝。</li><li><code>code</code> 匹配正则 <code>^(sh|sz|bj)\\d{6}$</code> —— 不匹配拒绝。</li><li><code>date</code> 为 DATE 类型 —— BIGINT/VARCHAR 必须先转再入库。</li><li><code>amount</code> 单位 = 元 —— 量级校验：大盘股日成交 1e8~1e10 元，超界告警。</li><li><code>turnover ∈ [0, 200]</code> —— 单位 %，超界告警。</li><li><code>qfq</code> 价格 = <code>daily.close × adj_factor.qfq_factor</code> —— 交叉校验前复权。</li></ol><h2 id="四、映射到-caliber-meta-表" tabindex="-1"><a class="header-anchor" href="#四、映射到-caliber-meta-表"><span>四、映射到 caliber_meta 表</span></a></h2><table><thead><tr><th>caliber_meta 字段</th><th>取值（v1）</th></tr></thead><tbody><tr><td>adjust</td><td>前复权（<code>adj_factor.qfq_factor</code>）</td></tr><tr><td>limit_caliber</td><td>涨跌停口径（<code>limit_price.limit_up/limit_down/limit_pct</code>）</td></tr><tr><td>cost_rate</td><td>0.0015</td></tr><tr><td>code_format</td><td><code>sz000001</code>（小写2字母+6位）</td></tr><tr><td>market_enum</td><td><code>{sh, sz, bj}</code></td></tr><tr><td>date_format</td><td>DATE（ISO）</td></tr><tr><td>amount_unit</td><td>元</td></tr><tr><td>volume_unit</td><td>股</td></tr></tbody></table><h2 id="五、待核实项-v1-遗留-→-已消化-6-项-剩-1-项" tabindex="-1"><a class="header-anchor" href="#五、待核实项-v1-遗留-→-已消化-6-项-剩-1-项"><span>五、待核实项（v1 遗留 → 已消化 6 项，剩 1 项）</span></a></h2><ul><li>[x] <strong>🔴 前复权口径（已权威验证，结论修正）</strong>：经 tushare + 腾讯双源验证——① 前复权价负值（茅台 2001 年 -314）是「前复权」真实数学性质（累计分红超股价），<strong>不是 bug</strong>；② <code>adj_factor</code> 表（hfq=6.25）与权威源（8.6463）不一致，是<strong>真的错表</strong>，弃用；③ 判决器核心是「收益率 pct_chg」，复权不影响收益率，pct_chg 已验证 4/4 与 tushare 一致。<strong>结论：收益率用 <code>pct_chg</code>（已验证）；技术指标用后复权价 <code>tech_factor_hfq.close</code>（正值单调）；<code>adj_factor</code> 表弃用。</strong></li><li>[x] <strong>🔴 第 7 个地雷：文件名后缀不稳定（已修复）</strong>：<code>(2)</code> 后缀不同日含义漂移。<strong>结论：同步 skill v3 改为按「表头签名」识别，不按文件名。</strong></li><li>[x] <code>limit_price.market</code> 混乱（已消化）：历史 1669 万行用 <code>hs</code> 合并，近期 1.5 万行才用 <code>sz/sh</code> 单独。<strong>归一从 code 前缀推导，忽略源 market 字段。</strong></li><li>[x] <code>suspension.交易日期</code>（已消化）：VARCHAR 存 <code>&#39;19990528&#39;</code>（8 位 YYYYMMDD），<code>normalize_date</code> 的 <code>%Y%m%d</code> 分支已能处理。</li><li>[x] <code>market_flow_daily</code>（已消化）：只有 2023-04-17 之后（851 行）。<strong>情绪指数维度只能回测 2023 之后，更早无两融数据。</strong></li><li>[x] <code>zt_pool</code> 主表滞后（已消化）：<code>zt_pool</code> 到 2026-09-17，但 <code>zt_pool_limit_up/down</code> 到 10-21。<strong>涨停池主表没持续导入，需补导或改用 limit_up/down 表。</strong></li><li>[x] <code>adj_factor</code> 缺记录（已确认根因）：下载包「复权因子_前复权.zip」里茅台 10-21 <strong>数据源本身就缺</strong>（最后一行是 10-20）。且「前复权因子负值」不是 bug（腾讯权威源前复权价也是 -314）。<strong>结论：adj_factor 表弃用（hfq=6.25 与权威源 8.6463 不一致）；收益率用 pct_chg，技术指标用 tech_factor_hfq.close。</strong></li></ul><h2 id="六、结论" tabindex="-1"><a class="header-anchor" href="#六、结论"><span>六、结论</span></a></h2><p>数据地基「料」够格，但要立住，第一步就是<strong>把上面 5 个地雷 + 4 个待核实项写成 <code>caliber_meta</code> 表 + QC 断言</strong>。这份契约 v1 已经把它们从「经验预判」变成了「实库实证」。下一步：数据管家照此建 <code>caliber_meta</code> 表 + 写 QC 门禁，回测判决官 harness 才能拿到可靠输入。</p>`,26)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};